package org.eclipse.kura.internal.rest.identity.provider.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.argThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Arrays;
import java.util.HashSet;

import javax.ws.rs.WebApplicationException;
import javax.ws.rs.container.ContainerRequestContext;

import org.eclipse.kura.KuraException;
import org.eclipse.kura.internal.rest.identity.provider.IdentityRestServiceV1;
import org.eclipse.kura.internal.rest.identity.provider.LegacyIdentityService;
import org.eclipse.kura.internal.rest.identity.provider.dto.UserDTO;
import org.eclipse.osgi.service.environment.EnvironmentInfo;
import org.junit.After;
import org.junit.Test;

/**
 * Feature: the -kura.rest.identity.legacyIdentityManagement framework command line argument restores the identity
 * management behaviour of the previous releases, where any identity holding rest.identity can manage all identities
 * and permissions.
 */
public class IdentityRestServiceV1LegacyIdentityManagementTest {

    private static final String LEGACY_ARGUMENT = "-kura.rest.identity.legacyIdentityManagement";

    private static final String ADMIN_PERMISSION = "kura.admin";
    private static final String IDENTITY_PERMISSION = "rest.identity";
    private static final String NOT_HELD_PERMISSION = "rest.command";

    private static final String MANAGER = "manager";
    private static final String TARGET = "target";

    private final InMemoryUserAdmin userAdmin = new InMemoryUserAdmin();
    private final LegacyIdentityService legacyIdentityService = mock(LegacyIdentityService.class);
    private final IdentityRestServiceV1 service = new IdentityRestServiceV1();

    private String[] frameworkCommandLineArguments = new String[0];
    private ContainerRequestContext requestContext;
    private WebApplicationException occurredException;

    /*
     * Scenarios
     */

    @Test
    public void legacyArgumentAllowsNonAdminToCreateUserWithAdminPermission() throws KuraException {
        givenFrameworkArguments("-otherArgument", LEGACY_ARGUMENT);
        givenIdentity(MANAGER, IDENTITY_PERMISSION);
        givenRequestFrom(MANAGER);

        whenUserIsCreated(TARGET, ADMIN_PERMISSION);

        thenNoExceptionOccurred();
        thenUserIsCreated(TARGET);
    }

    @Test
    public void legacyArgumentAllowsNonAdminToDeleteMorePrivilegedUser() throws KuraException {
        givenFrameworkArguments(LEGACY_ARGUMENT);
        givenIdentity(MANAGER, IDENTITY_PERMISSION);
        givenIdentity(TARGET, NOT_HELD_PERMISSION);
        givenRequestFrom(MANAGER);

        whenUserIsDeleted(TARGET);

        thenNoExceptionOccurred();
        thenUserIsDeleted(TARGET);
    }

    @Test
    public void systemPropertyWithTheSameNameIsIgnored() throws KuraException {
        givenSystemProperty("kura.rest.identity.legacyIdentityManagement", "true");
        givenSystemProperty("org.eclipse.kura.rest.identity.legacyIdentityManagement", "true");
        givenIdentity(MANAGER, IDENTITY_PERMISSION);
        givenRequestFrom(MANAGER);

        whenUserIsCreated(TARGET, ADMIN_PERMISSION);

        thenRequestIsForbidden();
        thenUserIsNotCreated();
    }

    @Test
    public void argumentWithValueIsIgnored() throws KuraException {
        givenFrameworkArguments(LEGACY_ARGUMENT + "=true");
        givenIdentity(MANAGER, IDENTITY_PERMISSION);
        givenRequestFrom(MANAGER);

        whenUserIsCreated(TARGET, ADMIN_PERMISSION);

        thenRequestIsForbidden();
        thenUserIsNotCreated();
    }

    @Test
    public void missingLegacyArgumentKeepsPermissionChecks() throws KuraException {
        givenFrameworkArguments("-otherArgument");
        givenIdentity(MANAGER, IDENTITY_PERMISSION);
        givenRequestFrom(MANAGER);

        whenUserIsCreated(TARGET, ADMIN_PERMISSION);

        thenRequestIsForbidden();
        thenUserIsNotCreated();
    }

    @After
    public void clearSystemProperties() {
        System.clearProperty("kura.rest.identity.legacyIdentityManagement");
        System.clearProperty("org.eclipse.kura.rest.identity.legacyIdentityManagement");
    }

    /*
     * Steps
     */

    /*
     * Given
     */

    private void givenFrameworkArguments(final String... arguments) {
        this.frameworkCommandLineArguments = arguments;
    }

    private void givenSystemProperty(final String name, final String value) {
        System.setProperty(name, value);
    }

    private void givenIdentity(final String name, final String... permissions) {
        this.userAdmin.addIdentity(name, permissions);
    }

    private void givenRequestFrom(final String name) {
        this.requestContext = InMemoryUserAdmin.requestFrom(name);
    }

    /*
     * When
     */

    private void whenUserIsCreated(final String name, final String... permissions) {
        bindService();
        final UserDTO user = new UserDTO();
        user.setUserName(name);
        user.setPermissions(new HashSet<>(Arrays.asList(permissions)));

        try {
            this.service.createUser(user, this.requestContext);
        } catch (final WebApplicationException e) {
            this.occurredException = e;
        }
    }

    private void whenUserIsDeleted(final String name) {
        bindService();
        final UserDTO user = new UserDTO();
        user.setUserName(name);

        try {
            this.service.deleteUser(user, this.requestContext);
        } catch (final WebApplicationException e) {
            this.occurredException = e;
        }
    }

    /*
     * Then
     */

    private void thenNoExceptionOccurred() {
        assertNull(this.occurredException);
    }

    private void thenRequestIsForbidden() {
        assertNotNull("expected a forbidden response", this.occurredException);
        assertEquals(403, this.occurredException.getResponse().getStatus());
    }

    private void thenUserIsCreated(final String name) throws KuraException {
        verify(this.legacyIdentityService).createUser(argThat(u -> u != null && name.equals(u.getUserName())));
    }

    private void thenUserIsNotCreated() throws KuraException {
        verify(this.legacyIdentityService, never()).createUser(any());
    }

    private void thenUserIsDeleted(final String name) throws KuraException {
        verify(this.legacyIdentityService).deleteUser(name);
    }

    /*
     * Utilities
     */

    private void bindService() {
        final EnvironmentInfo environmentInfo = mock(EnvironmentInfo.class);
        when(environmentInfo.getNonFrameworkArgs()).thenReturn(this.frameworkCommandLineArguments);

        this.service.bindEnvironmentInfo(environmentInfo);
        this.service.bindIdentityService(this.userAdmin.identityService());
        this.service.bindUserAdmin(this.userAdmin.get());
        this.service.bindLegacyIdentityService(this.legacyIdentityService);
        this.service.activate();
    }
}
